// --- Mutex and RAII Lock Guard ---
std::mutex mtx;
int shared_count = 0;

void safe_increment() {
    std::lock_guard<std::mutex> lock(mtx);
    shared_count++; // Critical section protected
}

// --- Condition Variable (Wait/Notify) ---
std::mutex mtx_cv;
std::condition_variable cv;
bool data_ready = false;

void wait_for_data() {
    std::unique_lock<std::mutex> lk(mtx_cv);
    cv.wait(lk, []{ return data_ready; });
    // Process data
}

void signal_data() {
    std::lock_guard<std::mutex> lk(mtx_cv);
    data_ready = true;
    cv.notify_all();
}

// --- Atomic Operations (Lock-free) ---
std::atomic<int> safe_counter{0};

void atomic_access() {
    safe_counter++;                 // Atomically increment
    int current = safe_counter.load();
    safe_counter.compare_exchange_weak(current, 0);
}

// --- Future and Promise (Asynchronous Result) ---
std::promise<int> promise;
std::future<int> future = promise.get_future();

std::thread t_producer([] {
    promise.set_value(42);
});

int result = future.get(); // Blocks until value is set
